const body = $input.first().json;
const texto = (body.texto || '').toLowerCase().trim();

if (!texto) return [{ json: { accion: 'error', respuesta: 'No entendí el comando', datos: null } }];

if (texto.match(/falt[ao]|anot[ao]|apunt[ao]|necesito|pide|pedir|añade|añadir|agreg/)) {
  const limpio = texto.replace(/falta[n]?|anota|apunta|necesito|pide|pedir|añade|añadir|agrega|que|me|:/gi, '').replace(/\s+/g, ' ').trim();
  return [{ json: { accion: 'anotar_faltante', articulo: limpio, respuesta: `Anotado: falta ${limpio}`, datos: { articulo: limpio } } }];
}

if (texto.match(/qu[eé] hay que hacer|tareas|pendiente|qu[eé] tengo|hoy que|hacer hoy/)) {
  return [{ json: { accion: 'consultar_tareas', respuesta: 'Consultando tus tareas...', datos: null } }];
}

if (texto.match(/pedido|pedidos|cu[aá]ntos hay|preparar/)) {
  return [{ json: { accion: 'consultar_pedidos', respuesta: 'Consultando pedidos pendientes...', datos: null } }];
}

if (texto.match(/cu[aá]nto[s]?|stock|quedan|hay de|tengo de/)) {
  const articulo = texto.replace(/cu[aá]ntos?|stock|quedan|hay de|tengo de|me/gi, '').replace(/\s+/g, ' ').trim();
  return [{ json: { accion: 'consultar_stock', articulo, respuesta: `Consultando stock de ${articulo}...`, datos: { articulo } } }];
}

if (texto.match(/resumen|c[oó]mo ha ido|ventas|hoy|d[ií]a/)) {
  return [{ json: { accion: 'resumen_dia', respuesta: 'Preparando el resumen de hoy...', datos: null } }];
}

if (texto.match(/notificaci[oó]n|notificaciones|avisos?|alertas?/)) {
  return [{ json: { accion: 'ver_notificaciones', respuesta: 'Consultando tus notificaciones...', datos: null } }];
}

return [{ json: { accion: 'no_entendido', respuesta: `No reconocí el comando: "${body.texto}". Puedes decir: qué hay que hacer, pedidos pendientes, stock de X, anotar que falta X, o resumen del día.`, datos: null } }];

const accion = $('Interpretar comando de voz').first().json.accion;
let respuesta = '';

if (accion === 'anotar_faltante') {
  const art = $('Interpretar comando de voz').first().json.datos.articulo;
  respuesta = `Anotado. He añadido a tus tareas que falta ${art}.`;
}
else if (accion === 'consultar_tareas') {
  const tareas = $input.all();
  if (!tareas || tareas.length === 0 || !tareas[0].json.descripcion) {
    respuesta = 'No tienes tareas pendientes. Todo al día!';
  } else {
    const lista = tareas.map(t => t.json.descripcion).join('. ');
    respuesta = `Tienes ${tareas.length} tarea${tareas.length > 1 ? 's' : ''} pendiente${tareas.length > 1 ? 's' : ''}. ${lista}.`;
  }
}
else if (accion === 'consultar_pedidos') {
  const pedidos = $input.all();
  if (!pedidos || pedidos.length === 0 || !pedidos[0].json.numero_pedido) {
    respuesta = 'No tienes pedidos pendientes. Estás al día!';
  } else {
    respuesta = `Tienes ${pedidos.length} pedido${pedidos.length > 1 ? 's' : ''} pendiente${pedidos.length > 1 ? 's' : ''} de preparar.`;
    if (pedidos.length <= 3) {
      const lista = pedidos.map(p => `el de ${p.json.nombre_cliente}`).join(', ');
      respuesta += ` Son: ${lista}.`;
    }
  }
}
else if (accion === 'consultar_stock') {
  const items = $input.all();
  if (!items || items.length === 0 || !items[0].json.nombre) {
    const art = $('Interpretar comando de voz').first().json.datos.articulo;
    respuesta = `No encontré ningún artículo con el nombre ${art}.`;
  } else {
    respuesta = items.map(i => `${i.json.nombre}: ${i.json.stock} unidades`).join('. ') + '.';
  }
}
else if (accion === 'resumen_dia') {
  const stats = $input.first().json;
  const pedidos = stats.pedidos || 0;
  const facturado = parseFloat(stats.facturado || 0).toFixed(2);
  respuesta = pedidos === 0 ? 'Hoy no hay pedidos registrados todavía.' : `Hoy llevas ${pedidos} pedido${pedidos > 1 ? 's' : ''} y has facturado ${facturado} euros.`;
}
else if (accion === 'ver_notificaciones') {
  const notifs = $input.all();
  if (!notifs || notifs.length === 0 || !notifs[0].json.mensaje) {
    respuesta = 'No tienes notificaciones sin leer. Todo tranquilo!';
  } else {
    respuesta = `Tienes ${notifs.length} notificación${notifs.length > 1 ? 'es' : ''} sin leer. La más reciente: ${notifs[0].json.mensaje}.`;
  }
}
else {
  respuesta = $('Interpretar comando de voz').first().json.respuesta;
}

return [{ json: { respuesta, accion } }];
